/*
 Problem: 1291. Sequential Digits
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.3 MB (71.77%)
 Tags: Enumeration
*/
class Solution {
public:
    vector<int> sequentialDigits(int low, int high) {
        vector<int> ans;
        string s = "123456789";

        int l = to_string(low).size();
        int r = to_string(high).size();

        for (int len = l; len <= r; ++len) {
            for (int i = 0; i + len <= 9; ++i) {
                int x = stoi(s.substr(i, len));
                if (x >= low && x <= high) ans.push_back(x);
            }
        }

        return ans;
    }
};
